+template<typename T, typename Callback>
+static auto weak_callback(T& obj, Callback&& callback)
+{
+    return [weak = obj.template make_weak_ptr<T>(), callback = forward<Callback>(callback)](auto&&... args) {
+        if constexpr (requires { obj.ref(); obj.unref(); }) {
+            if (auto strong = weak.strong_ref())
+                callback(*strong, forward<decltype(args)>(args)...);
+        } else {
+            if (weak)
+                callback(*weak, forward<decltype(args)>(args)...);
+        }
+    };
